const stamp = "2026-10-23T12:34:56.789Z"

// The goldens below are transcribed from our C application's printf templates,
// not generated by the Go formatter or by another IEC implementation.
func logs(lines ...string) string {
	var s strings.Builder
	for _, line := range lines {
		s.WriteString(stamp + " iec104cmd " + line + "\n")
	}
	return s.String()
}

func result(op, status string) string {
	return fmt.Sprintf("{\"event\":\"result\",\"at\":\"%s\",\"op\":\"%s\",\"status\":\"%s\"}\n", stamp, op, status)
}

func goldenFlag(b bool) int {
	if b {
		return 1
	}
	return 0
}

type capture struct {
	mu      sync.Mutex
	b       bytes.Buffer
	changed chan struct{}
}

func newCapture() *capture { return &capture{changed: make(chan struct{}, 1)} }
func (b *capture) Write(p []byte) (int, error) {
	b.mu.Lock()
	n, err := b.b.Write(p)
	b.mu.Unlock()
	notify(b.changed)
	return n, err
}
func (b *capture) String() string {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.b.String()
}
func (b *capture) await(ctx context.Context, text string) bool {
	for {
		if strings.Contains(b.String(), text) {
			return true
		}
		select {
		case <-ctx.Done():
			return false
		case <-b.changed:
		}
	}
}

func testRuntime() runtime {
	rt := defaults()
	at, _ := time.Parse(time.RFC3339Nano, stamp)
	rt.now = func() time.Time { return at }
	rt.timeout = 100 * time.Millisecond
	return rt
}

func peer(t *testing.T, handler iec.Handler) string {
	t.Helper()
	ctx, cancel := context.WithCancel(context.Background())
	opts := iec.DefaultOptions()
	opts.SendQueue = 256
	opts.Logf = func(format string, args ...any) { t.Logf(format, args...) }
	s, err := iec.NewServer(opts, handler)
	if err != nil {
		t.Fatal(err)
	}
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	done := make(chan error, 1)
	go func() { done <- s.Serve(ctx, listener) }()
	t.Cleanup(func() {
		cancel()
		closeCtx, closeCancel := context.WithTimeout(context.Background(), time.Second)
		defer closeCancel()
		if err := s.Shutdown(closeCtx); err != nil {
			t.Error(err)
		}
		select {
		case err := <-done:
			if err != nil {
				t.Error(err)
			}
		case <-closeCtx.Done():
			t.Error("server did not exit")
		}
	})
	return listener.Addr().String()
}

func send(t *testing.T, session *iec.Session, m iec.Message) {
	t.Helper()
	if err := session.Send(m); err != nil {
		t.Errorf("peer send: %v", err)
	}
}

func echo(a *iec.ASDU, cause iec.COT, negative bool) *iec.ASDU {
	h := a.Header
	h.Cause, h.Negative = cause, negative
	return &iec.ASDU{Header: h, Objects: append([]iec.Object(nil), a.Objects...)}
}

func TestOneShotGoldens(t *testing.T) {
	tests := []struct {
		name, argv, op, typ, object string
		mode                        string
		code                        int
		sbo                         bool
		execValue                   int
	}{
		{"gi-flags-after", "gi --json", "gi", "C_IC_NA_1(100)", "qoi=20", "", 0, false, 0},
		{"gi-flags-before", "--json -oa 0 -ca 0 gi", "gi", "C_IC_NA_1(100)", "qoi=20", "zero", 0, false, 0},
		{"gi-extra-words", "gi ignored --json", "gi", "C_IC_NA_1(100)", "qoi=20", "", 0, false, 0},
		{"gi-rejected", "gi --json", "gi", "C_IC_NA_1(100)", "qoi=20", "reject", 1, false, 0},
		{"gi-no-term", "gi --json", "gi", "C_IC_NA_1(100)", "qoi=20", "missing-term", 1, false, 0},
		{"stopstart", "stopstart --json", "stopstart", "", "", "", 0, false, 0},
		{"dc-direct", "dc 3001 open --json", "dc", "C_DC_NA_1(46)", "dcs=1(OFF) qu=0", "", 0, false, 1},
		{"dc-sbo-delay", "dc -ca 1 3001 close -delay-ms 15 --json", "dc", "C_DC_NA_1(46)", "dcs=2(ON) qu=0", "", 0, true, 2},
		{"rc-sbo", "rc 3301 lower -sbo --json", "rc", "C_RC_NA_1(47)", "rcs=1 qu=0", "", 0, true, 1},
		{"sc-sbo", "--json sc 3302 on -sbo", "sc", "C_SC_NA_1(45)", "scs=ON qu=0", "", 0, true, 1},
		{"sc-off", "sc 3302 off --json", "sc", "C_SC_NA_1(45)", "scs=OFF qu=0", "", 0, false, 0},
		{"select-rejected", "dc 3001 open -sbo --json", "dc", "C_DC_NA_1(46)", "dcs=1(OFF) qu=0", "reject", 1, true, 1},
		{"execute-rejected", "rc 3301 raise --json", "rc", "C_RC_NA_1(47)", "rcs=2 qu=0", "reject", 1, false, 2},
		{"execute-no-confirm", "dc 3001 open --json", "dc", "C_DC_NA_1(46)", "dcs=1(OFF) qu=0", "missing-con", 1, false, 1},
		{"execute-no-term", "dc 3001 open --json", "dc", "C_DC_NA_1(46)", "dcs=1(OFF) qu=0", "missing-term", 1, false, 1},
		{"execute-negative-term", "dc 3001 open --json", "dc", "C_DC_NA_1(46)", "dcs=1(OFF) qu=0", "negative-term", 1, false, 1},
		{"dc-mismatch", "dc 3001 open -mismatch --json", "dc", "C_DC_NA_1(46)", "dcs=1(OFF) qu=0", "mismatch", 1, true, 2},
		{"rc-mismatch", "rc 3301 lower -mismatch --json", "rc", "C_RC_NA_1(47)", "rcs=1 qu=0", "mismatch", 1, true, 2},
		{"sc-mismatch", "sc 3302 on -mismatch --json", "sc", "C_SC_NA_1(45)", "scs=ON qu=0", "mismatch", 1, true, 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			out, errout := newCapture(), newCapture()
			var selectedAt time.Time
			addr := peer(t, func(ctx context.Context, e iec.Event) {
				if e.Kind != iec.ASDUReceived {
					return
				}
				a := e.ASDU.(*iec.ASDU)
				wantOA, wantCA := uint8(1), uint16(1)
				if tt.mode == "zero" {
					wantOA, wantCA = 0, 0
				}
				if a.Header.Cause != iec.Activation || a.Header.Originator != wantOA || a.Header.CommonAddress != wantCA {
					t.Errorf("request header: %+v", a.Header)
				}
				selecting := false
				switch v := a.Objects[0].Element.(type) {
				case iec.SingleCommand:
					selecting = v.Qualifier.Select()
					if !selecting && int(v.Qualifier.State()) != tt.execValue {
						t.Errorf("execute value: %d", v.Qualifier.State())
					}
				case iec.DoubleCommand:
					selecting = v.Qualifier.Select()
					if !selecting && int(v.Qualifier.State()) != tt.execValue {
						t.Errorf("execute value: %d", v.Qualifier.State())
					}
				case iec.RegulatingCommand:
					selecting = v.Qualifier.Select()
					if !selecting && int(v.Qualifier.State()) != tt.execValue {
						t.Errorf("execute value: %d", v.Qualifier.State())
					}
				}
				if selecting {
					selectedAt = time.Now()
				} else if tt.name == "dc-sbo-delay" && time.Since(selectedAt) < 15*time.Millisecond {
					t.Error("delay was not observed")
				}
				if tt.mode == "missing-con" {
					return
				}
				negative := tt.mode == "reject" || (tt.mode == "mismatch" && !selecting)
				send(t, e.Session, echo(a, iec.ActivationCon, negative))
				if negative || selecting || tt.mode == "missing-term" {
					return
				}
				if tt.op != "gi" {
					waitCtx, cancel := context.WithTimeout(ctx, time.Second)
					defer cancel()
					if !errout.await(waitCtx, "execute confirmed\n") {
						t.Error("execute confirmation not consumed")
						return
					}
				}
				send(t, e.Session, echo(a, iec.ActivationTerm, tt.mode == "negative-term"))
			})
			ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
			defer cancel()
			code := run(ctx, append([]string{addr}, strings.Fields(tt.argv)...), out, errout, testRuntime())
			if code != tt.code {
				t.Fatalf("exit=%d want=%d\n%s", code, tt.code, errout.String())
			}
			status := "ok"
			if code != 0 {
				status = "failed"
			}
			if got, want := out.String(), result(tt.op, status); got != want {
				t.Errorf("stdout:\n%s\nwant:\n%s", got, want)
			}
			oa, ca := 1, 1
			if tt.mode == "zero" {
				oa, ca = 0, 0
			}
			want := logs(fmt.Sprintf("connecting to %s oa=%d ca=%d", addr, oa, ca), "link opened", "link startdt-con", "link started")
			ioa := map[string]int{"gi": 0, "dc": 3001, "rc": 3301, "sc": 3302}[tt.op]
			rx := func(cot string, neg int, object string) string {
				text := logs(fmt.Sprintf("rx ASDU type=%s cot=%s neg=%d test=0 oa=%d ca=%d objects=1", tt.typ, cot, neg, oa, ca))
				return text + logs(fmt.Sprintf("rx   ioa=%d %s", ioa, object))
			}
			switch tt.op {
			case "gi":
				want += logs("send station GI")
				neg := goldenFlag(tt.mode == "reject")
				want += rx("actcon(7)", neg, "qoi=20")
				if tt.code == 0 {
					want += rx("actterm(10)", 0, "qoi=20") + logs("GI terminated")
				} else {
					if tt.mode == "reject" {
						want += logs("GI confirmation rejected (cot=actcon(7) negative=1)")
					}
					want += logs("GI not confirmed")
				}
			case "stopstart":
				want += logs("link stopdt-con", "link startdt-con", "STOPDT then STARTDT confirmed")
			default:
				initial := tt.execValue
				if tt.mode == "mismatch" {
					if tt.op == "sc" {
						initial = 1 - initial
					} else {
						initial = 3 - initial
					}
				}
				if tt.sbo {
					want += logs(fmt.Sprintf("SELECT ioa=%d val=%d", ioa, initial))
					want += rx("actcon(7)", goldenFlag(tt.mode == "reject"), tt.object+" se=SELECT")
					if tt.mode == "reject" {
						want += logs("select REJECTED (negative)")
					} else {
						want += logs("select confirmed")
					}
				}
				if tt.name == "dc-sbo-delay" {
					want += logs("waiting 15ms before execute")
				}
				if !(tt.mode == "reject" && tt.sbo) {
					want += logs(fmt.Sprintf("EXECUTE ioa=%d val=%d", ioa, tt.execValue))
					obj := tt.object
					if tt.mode == "mismatch" {
						obj = map[string]string{"dc": "dcs=2(ON) qu=0", "rc": "rcs=2 qu=0", "sc": "scs=OFF qu=0"}[tt.op]
					}
					if tt.mode == "missing-con" {
						want += logs("no execute confirmation")
					} else {
						neg := tt.mode == "reject" || tt.mode == "mismatch"
						want += rx("actcon(7)", goldenFlag(neg), obj+" se=EXECUTE")
						if neg {
							want += logs("execute REJECTED (negative)")
						} else {
							want += logs("execute confirmed")
							if tt.mode == "missing-term" {
								want += logs("no execute termination (ACT-TERM)")
							} else {
								want += rx("actterm(10)", goldenFlag(tt.mode == "negative-term"), obj+" se=EXECUTE")
								want += logs(fmt.Sprintf("execute terminated (ACT-TERM) negative=%d", goldenFlag(tt.mode == "negative-term")))
							}
						}
					}
				}
			}
			want += logs("link closed")
			if got := errout.String(); got != want {
				t.Errorf("stderr:\n%s\nwant:\n%s", got, want)
			}
		})
	}
}

func TestConnectFailureGolden(t *testing.T) {
	for _, realTransport := range []bool{false, true} {
		t.Run(fmt.Sprint(realTransport), func(t *testing.T) {
			rt := testRuntime()
			addr := "127.0.0.1:2404"
			if realTransport {
				l, err := net.Listen("tcp", "127.0.0.1:0")
				if err != nil {
					t.Fatal(err)
				}
				addr = l.Addr().String()
				if err := l.Close(); err != nil {
					t.Fatal(err)
				}
			} else {
				rt.dial = func(context.Context, string, iec.Options, iec.Handler) (link, error) {
					return nil, errors.New("fixture refuses connection")
				}
			}
			var out, errout bytes.Buffer
			ctx, cancel := context.WithTimeout(context.Background(), time.Second)
			defer cancel()
			code := run(ctx, []string{addr, "gi", "--json"}, &out, &errout, rt)
			want := logs("connecting to "+addr+" oa=1 ca=1", "connect failed")
			if code != 2 || out.Len() != 0 || errout.String() != want {
				t.Fatalf("exit=%d stdout=%q stderr=%q want=%q", code, out.String(), errout.String(), want)
			}
		})
	}
}

func TestUsageGoldens(t *testing.T) {
	for _, args := range [][]string{
		nil, {"host"}, {"-ca", "gi"}, {":2404", "gi"}, {"host:0", "gi"},
		{"host:65536", "gi"}, {strings.Repeat("a", 128), "gi"},
		{"host", "gi", "-oa", "256"}, {"host", "gi", "-ca", "-1"},
		{"host", "monitor", "--hold", "0"}, {"host", "monitor", "--gi-every", "86401"},
		{"host", "dc", "1", "open", "-delay-ms", "600001"},
		{"host", "gi", "-oa"}, {"host", "gi", "--"}, {"host", "gi", "--unknown"},
		{"host", "a", "b", "c", "d", "e", "f", "g", "h", "i"},
	} {
		t.Run(strings.Join(args, "_"), func(t *testing.T) {
			rt := testRuntime()
			rt.dial = func(context.Context, string, iec.Options, iec.Handler) (link, error) {
				t.Error("usage must not dial")
				return nil, errors.New("unexpected dial")
			}
			var out, errout bytes.Buffer
			code := run(context.Background(), args, &out, &errout, rt)
			if code != 2 || out.Len() != 0 || errout.String() != usage {
				t.Fatalf("exit=%d stdout=%q stderr=%q", code, out.String(), errout.String())
			}
		})
	}
}

func TestOperationUsageAfterConnect(t *testing.T) {
	for _, args := range []string{"unknown", "monitor", "stopstart extra", "dc 16777216 open", "dc 3001 bad", "rc 1 up", "sc 1 true", "sc 1"} {
		t.Run(args, func(t *testing.T) {
			addr := peer(t, nil)
			out, errout := newCapture(), newCapture()
			ctx, cancel := context.WithTimeout(context.Background(), time.Second)
			defer cancel()
			code := run(ctx, append([]string{addr, "--json"}, strings.Fields(args)...), out, errout, testRuntime())
			want := logs("connecting to "+addr+" oa=1 ca=1", "link opened", "link startdt-con", "link started") + usage
			if code != 2 || out.String() != "" || errout.String() != want {
				t.Fatalf("exit=%d stdout=%q stderr=%q want=%q", code, out.String(), errout.String(), want)
			}
		})
	}
}

func TestHumanOutputGolden(t *testing.T) {
	addr := peer(t, func(_ context.Context, e iec.Event) {
		if e.Kind == iec.ASDUReceived {
			a := e.ASDU.(*iec.ASDU)
			send(t, e.Session, echo(a, iec.ActivationCon, false))
			send(t, e.Session, echo(a, iec.ActivationTerm, false))
		}
	})
	out, errout := newCapture(), newCapture()
	ctx, cancel := context.WithTimeout(context.Background(), time.Second)
	defer cancel()
	code := run(ctx, []string{addr, "gi"}, out, errout, testRuntime())
	want := logs("connecting to "+addr+" oa=1 ca=1", "link opened", "link startdt-con", "link started", "send station GI",
		"rx ASDU type=C_IC_NA_1(100) cot=actcon(7) neg=0 test=0 oa=1 ca=1 objects=1", "rx   ioa=0 qoi=20",
		"rx ASDU type=C_IC_NA_1(100) cot=actterm(10) neg=0 test=0 oa=1 ca=1 objects=1", "rx   ioa=0 qoi=20",
		"GI terminated", "link closed")
	if code != 0 || errout.String() != "" || out.String() != want {
		t.Fatalf("exit=%d stdout=%q stderr=%q want=%q", code, out.String(), errout.String(), want)
	}
}
